import com.sun.tools.javac.parser.ParserFactory;
import com.sun.tools.javac.tree.JCTree;
import com.sun.tools.javac.util.Context;
import com.sun.tools.javac.util.Log;
import javax.tools.JavaFileObject;

public class Dump {
    static StringBuilder sb = new StringBuilder();
    static int indent = 0;

    static void p(Object... args) {
        for (int i = 0; i < indent; i++) sb.append("  ");
        sb.append(java.util.Arrays.toString(args)).append("\n");
    }

    static void dump(JCTree t) {
        if (t == null) { p("null"); return; }
        String cls = t.getClass().getSimpleName();
        switch (cls) {
            case "JCModifiers": {
                com.sun.tools.javac.tree.JCTree.JCModifiers m = (com.sun.tools.javac.tree.JCTree.JCModifiers) t;
                p("JCModifiers flags=" + Long.toHexString(m.flags) + " annos=" + m.annotations);
                return;
            }
            case "JCAnnotatedType": {
                com.sun.tools.javac.tree.JCTree.JCAnnotatedType at = (com.sun.tools.javac.tree.JCTree.JCAnnotatedType) t;
                p("JCAnnotatedType");
                indent++;
                for (JCTree.JCAnnotation a : at.annotations) dump(a);
                p("underlying:");
                indent++; dump(at.underlyingType); indent--;
                indent--;
                return;
            }
            case "JCArrayTypeTree": {
                com.sun.tools.javac.tree.JCTree.JCArrayTypeTree arr = (com.sun.tools.javac.tree.JCTree.JCArrayTypeTree) t;
                p("JCArrayTypeTree");
                indent++; p("elemtype:"); indent++; dump(arr.elemtype); indent--; indent--;
                return;
            }
            case "JCAnnotation": {
                com.sun.tools.javac.tree.JCTree.JCAnnotation an = (com.sun.tools.javac.tree.JCTree.JCAnnotation) t;
                p("JCAnnotation " + an.annotationType + " attrMode=" + an.getAnnotationType());
                return;
            }
            case "JCIdent": {
                p("JCIdent " + ((com.sun.tools.javac.tree.JCTree.JCIdent) t).name);
                return;
            }
            case "JCVariableDecl": {
                com.sun.tools.javac.tree.JCTree.JCVariableDecl v = (com.sun.tools.javac.tree.JCTree.JCVariableDecl) t;
                p("JCVariableDecl name=" + v.name);
                indent++;
                p("mods:"); indent++; dump(v.mods); indent--;
                p("vartype:"); indent++; dump(v.vartype); indent--;
                indent--;
                return;
            }
            case "JCClassDecl": {
                com.sun.tools.javac.tree.JCTree.JCClassDecl c = (com.sun.tools.javac.tree.JCTree.JCClassDecl) t;
                p("JCClassDecl " + c.getSimpleName());
                indent++;
                for (JCTree def : c.defs) dump(def);
                indent--;
                return;
            }
            default: p(cls);
        }
    }

    public static void main(String[] args) throws Exception {
        Context ctx = new Context();
        Log.instance(ctx).useSource(args.length > 0 ? null : null);
        JavacFileManager fm = (JavacFileManager) com.sun.tools.javac.util.JavacFileManager.preRegister(ctx);
        JavaFileObject src = fm.getJavaFileObjects(new java.io.File(args[0])).iterator().next();
        Log.instance(ctx).useSource(src);
        ParserFactory pf = ParserFactory.instance(ctx);
        com.sun.tools.javac.parser.Parser parser = pf.parseParser(src, null);
        JCTree.JCCompilationUnit cu = parser.parseCompilationUnit();
        for (JCTree def : cu.defs) dump(def);
        System.out.println(sb);
    }
}

