public void rebuild(boolean force) {
	propagateProblems();
	if (completeParse && !force) return;
	boolean changed = isChanged();
	boolean newCompleteParse = isComplete(compilationUnitDeclaration);
	if (!newCompleteParse && !force) return;

	top().rebuild();

