import com.sun.source.tree.*;
import com.sun.source.util.*;
import javax.tools.*;
import java.net.URI;
import java.util.*;

public class Dump3 {
    static class MemFile extends SimpleJavaFileObject {
        final String code;
        MemFile(String name, String code) { super(URI.create("mem:///" + name), Kind.SOURCE); this.code = code; }
        public CharSequence getCharContent(boolean b) { return code; }
    }

    static void indent(int n) { for (int i = 0; i < n; i++) System.out.print("  "); }

    static void dump(Tree t, int ind) {
        if (t == null) { indent(ind); System.out.println("null"); return; }
        indent(ind);
        System.out.println(t.getKind() + "  [" + t.getClass().getSimpleName() + "]");
        if (t instanceof AnnotatedTypeTree) {
            for (AnnotationTree a : ((AnnotatedTypeTree) t).getAnnotations()) dump(a, ind + 1);
            dump(((AnnotatedTypeTree) t).getUnderlyingType(), ind + 1);
        } else if (t instanceof ArrayTypeTree) {
            dump(((ArrayTypeTree) t).getType(), ind + 1);
        } else if (t instanceof PrimitiveTypeTree) {
            indent(ind + 1); System.out.println(((PrimitiveTypeTree) t).getPrimitiveTypeKind());
        } else if (t instanceof MemberSelectTree) {
            indent(ind + 1); System.out.println(((MemberSelectTree) t).getIdentifier());
        } else if (t instanceof IdentifierTree) {
            indent(ind + 1); System.out.println(((IdentifierTree) t).getName());
        }
    }

    public static void main(String[] args) throws Exception {
        String code = String.join("\n",
            "import java.lang.annotation.*;",
            "@Target({ElementType.TYPE_USE, ElementType.FIELD, ElementType.RECORD_COMPONENT}) @interface N {}",
            "record R(@N int[] a, int @N [] b, int[] @N [] c) {}"
        );
        JavaCompiler comp = ToolProvider.getSystemJavaCompiler();
        JavacTask task = (JavacTask) comp.getTask(null, null, null, List.of("-proc:none"), null, List.of(new MemFile("R.java", code)));
        Iterable<? extends CompilationUnitTree> units = task.parse();
        task.analyze(); // runs enter + attribution; annotations may be repositioned
        for (CompilationUnitTree unit : units) {
            for (Tree t : unit.getTypeDecls()) {
                if (t instanceof ClassTree) {
                    for (Tree m : ((ClassTree) t).getMembers()) {
                        if (m instanceof VariableTree) {
                            VariableTree v = (VariableTree) m;
                            System.out.println("VAR " + v.getName() + "  modsAnnos=" + v.getModifiers().getAnnotations());
                            System.out.println("  type tree:");
                            dump(v.getType(), 2);
                        }
                    }
                }
            }
        }
    }
}

